insert into public.collections (slug, name, intro, hero_image, sort_order, is_seasonal) values
  ('kingdom', 'Kingdom', 'Scripture worn loud. Full verses and short declarations in bold type, made for people who do not whisper their faith.', '/placeholders/tee.svg', 1, false),
  ('word', 'Word', 'The Word, front and centre. Type-led pieces built around the lines that carry you through the week.', '/placeholders/tee.svg', 2, false),
  ('naija-mood', 'Naija Mood', 'Faith with our own voice. Pidgin, humour and everyday confidence, because God understands every accent.', '/placeholders/tee.svg', 3, false),
  ('two-of-us', 'Two of Us', 'Matching pieces for two. Pick a design, set his and hers sizes, and let the pair do the talking.', '/placeholders/tee.svg', 4, false),
  ('christmas-drop', 'Christmas Drop', 'The season, simply said. Limited Christmas designs that get to you in time, if you order before the cutoff.', '/placeholders/gift-box.svg', 5, true),
  ('accessories', 'Accessories', 'Bracelets, perfume, jewellery, glasses and a few fun extras. Small things that finish the look and make good gifts.', '/placeholders/bracelet.svg', 6, false);
